const payload = $input.first().json;
const assetA = payload.assetA || 'BTC';
const assetB = payload.assetB || 'ETH';
const priceA = payload.priceA || 64200;
const priceB = payload.priceB || 3450;

const ratio = priceA / priceB;
const rollingMean = payload.meanRatio || 18.25;
const rollingStd = payload.stdRatio || 0.42;
const zScore = Math.round(((ratio - rollingMean) / rollingStd) * 100) / 100;

let signal = 'NEUTRAL';
if (zScore <= -2.0) signal = 'LONG_A_SHORT_B';
else if (zScore >= 2.0) signal = 'SHORT_A_LONG_B';

return {
  json: {
    pair: `${assetA}/${assetB}`,
    currentRatio: Math.round(ratio * 100) / 100,
    rollingMean,
    zScore,
    signal,
    halfLifeDays: 4.2,
    isDivergent: Math.abs(zScore) >= 2.0
  }
};

const prev = $input.first().json;
const text = prev.content || prev.output || JSON.stringify(prev);

return {
  json: {
    success: true,
    botId: 'statistical-arbitrage',
    botName: 'Statistical Arbitrage & Pairs Trading Agent',
    status: 'PAIRS_REBALANCING_CALCULATED',
    strategyOutput: text,
    timestamp: new Date().toISOString()
  }
};
